/** Response of POST /school-settings/new-registration */
export interface CreateNewRegistrationResponse {
  success: boolean;
  message: string;
  data?: {
    _id: string;
    /** Auto-generated by the backend, per school + session. */
    regno: number;
  };
}

/** One registration as returned by GET /school-settings/get-all-newregstration */
export interface RegisteredStudent {
  _id: string;
  regno: number;
  /** Session `_id` (not populated by the backend) — resolve the name via the sessions list. */
  session: string;
  schId: string;
  schCode: string;
  sname: string;
  fname: string;
  mname: string;
  gname: string;
  gender: "male" | "female" | "other";
  category: "general" | "obc" | "sc" | "st";
  age: number;
  dob?: string;
  mothertongue: string;
  secLang?: string;
  nationality: string;
  religion: string;
  penno?: string;
  mob1: string;
  mob2?: string;
  whatAppno: string;
  adharId?: string;
  email?: string;
  lclass?: string;
  lper?: number;
  lsch?: string;
  lboard?: string;
  /** Backend shape: `{ classID, sectionID? }`. The list API returns raw ObjectIds,
   *  the by-id API returns populated objects. A plain string is the legacy shape.
   *  Use `getClassApplyforId` (lib/classApplyfor.ts) to read the class id. */
  classApplyfor?:
    | string
    | {
        classID?: string | { _id: string; className?: string; classInWord?: string };
        sectionID?: string | { _id: string; sectionName?: string };
      };
  registrationdate?: string;
  /** File name only; served from <apiBaseUrl>/uploads/studentImage/<Image> */
  Image?: string;
  status?: "pending" | "admitted" | "rejected";
  admdate?: string;
  createdAt?: string;
}

export interface GetAllNewRegistrationsResponse {
  success: boolean;
  message: string;
  count: number;
  data: RegisteredStudent[];
}

/** Response of GET /school-settings/get-register-studbyid?regno=&schId= */
export interface GetRegisteredStudentByIdResponse {
  success: boolean;
  message: string;
  data: RegisteredStudent | null;
}

/** Request body of POST /school-settings/stud-admission */
export interface AdmitStudentRequest {
  /** NOT the human-readable regno — this is the registration document's own `_id`. */
  regno: string;
  admno: string;
  session: string;
  classID: string;
  sectionId: string;
  rollNo?: string;
  admissionDate?: string;
  schId: string;
}

export interface AdmitStudentResponse {
  success: boolean;
  message: string;
  data?: {
    student: {
      _id: string;
      admno: string;
      regno: string;
      admissionSession: string;
      admissionDate: string;
    };
    enrollment: {
      _id: string;
      classID: string;
      sectionId: string;
      rollNo?: string;
    };
    demandsCreated?: unknown;
  };
}
